#pragma once
// A deliberately local, rule-based conversation companion. No hidden API,
// language model, telemetry or pretending to know unsupported answers.
namespace Bratuha {
struct Message {bool user=false;std::string text;};
static std::vector<Message> history;
static bool loaded,swearing=true,scroll;
static unsigned serial;
static std::deque<std::string> recentReplies;
static ULONGLONG answerAt;
static std::string pending,topic;
static std::string fold(const std::string &text){auto w=Hud::wide(text);if(!w.empty())CharLowerBuffW(w.data(),w.size());return Hud::utf8(w);}
static bool contains(const std::string &text,std::initializer_list<const char *> terms){for(auto term:terms)if(text.find(term)!=std::string::npos)return true;return false;}
static std::string choose(std::initializer_list<const char *> list){
    if(!list.size())return {};size_t start=serial%list.size();std::string value;
    for(size_t i=0;i<list.size();++i){value=*(list.begin()+(start+i)%list.size());if(std::find(recentReplies.begin(),recentReplies.end(),value)==recentReplies.end())break;}
    recentReplies.push_back(value);while(recentReplies.size()>4)recentReplies.pop_front();return value;
}
static bool arithmetic(const std::string &text,std::string &result){
    for(size_t i=0;i<text.size();++i){if(!std::isdigit(static_cast<unsigned char>(text[i]))&&text[i]!='-')continue;char *end=nullptr;double a=strtod(text.c_str()+i,&end);if(end==text.c_str()+i)continue;
        while(*end==' ')++end;char op=*end;if(!op||!strchr("+-*/",op))continue;char *tail=nullptr;double b=strtod(end+1,&tail);if(tail==end+1||!std::isfinite(a)||!std::isfinite(b)||std::fabs(a)>1e12||std::fabs(b)>1e12)continue;
        if(op=='/'&&b==0){result=u8"На ноль делить нельзя, брат. Даже если очень уверенно нажать Enter.";return true;}
        double value=op=='+'?a+b:op=='-'?a-b:op=='*'?a*b:a/b;char number[96];snprintf(number,sizeof(number),"%.10g",value);result=std::string(u8"Получается ")+number+u8". Хоть тут без разброса.";return true;
    }return false;
}
static std::string reply(const std::string &input){
    auto text=fold(input);auto start=text.find_first_not_of(" \r\n\t");if(start!=std::string::npos)text.erase(0,start);while(!text.empty()&&std::isspace(static_cast<unsigned char>(text.back())))text.pop_back();++serial;std::string math;if(arithmetic(text,math))return math;
    if(contains(text,{u8"убить себя",u8"самоуб",u8"не хочу жить"}))return u8"Брат, тут без подколов. Не оставайся с этим один: напиши человеку, которому доверяешь, и попроси побыть рядом. Если опасность прямо сейчас — обратись в местную экстренную службу. Я простой локальный бот и не могу заменить живую помощь.";
    if(contains(text,{u8"ты человек",u8"ты живой",u8"ты ии",u8"ты нейро"}))return u8"Я бот в твоём HUD, брат. Человеку в такой маленькой вкладке было бы тесновато.";
    if(contains(text,{u8"кто ты",u8"как тебя зовут"}))return u8"БРАТУХА. Местный поставщик подколов и советов, которые ты всё равно проверишь на собственной шкуре. Чё у тебя?";
    if(contains(text,{u8"тупой бот",u8"ты тупой",u8"не понимаешь",u8"опять одно"}))return choose({u8"Так, отдел контроля качества уже на месте. Давай без кругов: что именно я не так понял?",u8"Ладно, этот подкол засчитан. Сформулируй по-простому — попробуем ещё раз, без лекции на полэкрана.",u8"Поймал, брат. Сбавляю умный вид. О чём ты хотел поговорить?"});
    if(contains(text,{u8"чё как",u8"че как",u8"как сам",u8"как жизнь"}))return choose({u8"На месте, брат. Сижу красивый, пользы пока под вопросом. У тебя что за движ?",u8"Живём. Ты сегодня тащишь или пока чисто создаёшь атмосферу?",u8"Нормально. Планировал стать серьёзным, но ты зашёл — планы отменяются. Как сам?"});
    if(contains(text,{u8"пиздец",u8"заебал",u8"бесит",u8"раздраж",u8"достало",u8"всё плохо",u8"все плохо"}))return choose({u8"Так, выдыхай. Что произошло — катка, люди или день решил пройти тебя на максимальной сложности?",u8"Понял, сегодня мир опять играет против твоей нервной системы. Давай, выкладывай, что случилось.",u8"Не держи в себе, брат. Кто или что на этот раз получил премию «ну и хрень»?"});
    if(contains(text,{u8"заебись",u8"отлично",u8"кайф",u8"круто",u8"всё хорошо",u8"все хорошо"}))return choose({u8"Вот это разговор. Так и запишем в воображаемую летопись: братуха сегодня в порядке. Что хорошего?",u8"Во, уже лучше. Что за удача тебя накрыла — делись, я тоже порадуюсь.",u8"Красиво. Главное теперь не испортить момент фразой «ещё одна последняя катка». Что дальше планируешь?"});
    if(contains(text,{u8"сходил",u8"купил",u8"ездил",u8"посмотрел",u8"послушал",u8"сделал",u8"получилось",u8"нашёл",u8"нашел"}))return choose({u8"О, уже события подъехали. Ну и как — доволен или это была дорогая ошибка с красивой упаковкой?",u8"Так-так, с этого места подробнее. Что в итоге получилось?",u8"Нормальный движ. А сам как оцениваешь: удачно вышло или есть к чему придраться?"});
    if(contains(text,{u8"без мата",u8"не матерись"})){swearing=false;return u8"Принял, брат. Убираю мат, подколы оставляю на минималках.";}
    if(contains(text,{u8"с матом",u8"можно мат",u8"матерись"})){swearing=true;return u8"Ну всё, бля, цензурный отдел ушёл на обед. Но без злобы — мы же свои.";}
    if(contains(text,{u8"привет",u8"здоров",u8"салам",u8"йоу"}))return choose({u8"Здарова, брат! Как жизнь — тащишь или сегодня сервер тебя воспитывает?",u8"О, свои подъехали. Чё обсуждаем: игру, музыку, шмот или вообще жизнь?",u8"Здорово! Располагайся. Чай воображаемый, разговор настоящий. Как день?"});
    if(contains(text,{u8"спасибо",u8"благодар"}))return choose({u8"Да без проблем, брат. С тебя виртуальный чай, с меня сомнительные шутки.",u8"Обращайся. Сегодня даже без счёта за консультацию.",u8"Рад помочь, брат. Погнали дальше."});
    if(contains(text,{u8"пока",u8"до встречи",u8"спокойной ночи"}))return u8"Давай, брат. Отдыхай тоже, а не только катки жми. Будешь нужен — я тут.";
    if(contains(text,{u8"fps_visual",u8"фпс визуал",u8"герцовк"}))return u8"Загляни в CS Fix (Garey). fps_visual меняет визуальную частоту; стандарт 100, диапазон 20–1000. Если написано «Ожидание», модуль ещё не предоставил переменную — одно число в ползунке эффекта не создаёт.";
    if(contains(text,{"fog",u8"фоги",u8"фог"}))return u8"FOG — кадры на земле перед отрывом. HUD предпочитает свежие значения сервера; если их нет, показывает локальный расчёт. Правила серверных плагинов могут отличаться — отсюда и расхождения.";
    if(contains(text,{u8"сохранить конфиг",u8"где конфиг",u8"сохранить настройки"}))return u8"В Misc / Конфигурация можно сохранить текущие настройки или отдельный профиль. Обычные изменения HUD тоже сохраняет между запусками.";
    if(contains(text,{u8"как открыть",u8"не открывается меню"}))return u8"Insert открывает BALONCUAGA в игре, главном меню и поверх паузы. Escape закрывает HUD. F11 — выгрузка BALONCUAGA; оригинальный CS Fix остаётся до закрытия игры.";
    if(contains(text,{u8"смени сервер",u8"как зайти",u8"избранн",u8"список сервер"}))return u8"Открой «Серверы»: там история и избранное Steam. Выдели сервер и жми «Подключиться». Звезда меняет избранное; удаление работает с выбранными записями текущего списка.";
    if(contains(text,{u8"шутк",u8"анекдот",u8"подколи",u8"рофл"}))return choose({u8"Твой прицел настолько вежливый, что заранее обходит соперников стороной.",u8"Купил дорогие кроссы, чтобы быстрее бежать на респаун. Экономически спорно, но стильно.",u8"Говоришь «последняя катка» так уверенно, будто мы оба не знаем этот сериал.",u8"Сервер: задержка 20 мс. Ты после промаха: международный заговор кабельных провайдеров."});
    if(contains(text,{u8"груст",u8"плохой день",u8"устал",u8"одинок",u8"плохо на душе"}))return choose({u8"Брат, выдохни. Иногда лучший мув — вода, еда и десять минут без экрана. Хочешь, просто поболтаем?",u8"Бывает, что день играет грязнее любого сервера. Что сильнее достало — люди, дела или всё сразу?",u8"Без подколов сейчас. Не обязан весь день тащить. Расскажи, что случилось."});
    if(contains(text,{u8"как дела",u8"как ты",u8"чё делаешь",u8"что делаешь"}))return choose({u8"Сижу в HUD, делаю вид, что у меня работа. А у тебя как день?",u8"Нормально, брат. Пинг до холодильника нулевой, но доступа к нему нет. Что у тебя?",u8"Держусь. Тебя жду, чтоб обсудить что-нибудь кроме очередного промаха."});
    if(contains(text,{u8"музык",u8"трек",u8"песн",u8"рэп",u8"реп",u8"альбом",u8"слушаю",u8"слушать",u8"бит",u8"фонк"}))topic="music";
    else if(contains(text,{u8"фильм",u8"сериал",u8"кино",u8"аниме",u8"смотрю",u8"посмотреть",u8"ютуб",u8"youtube"}))topic="movies";
    else if(contains(text,{u8"кросс",u8"шмот",u8"одежд",u8"ветем",u8"rick",u8"balenci",u8"стиль",u8"ботинки",u8"худи",u8"штаны",u8"шмотки"}))topic="fashion";
    else if(contains(text,{u8"еду",u8"еды",u8"есть",u8"пицц",u8"бургер",u8"готовить",u8"чай",u8"кофе",u8"покуш",u8"жрать",u8"макарон",u8"суши"}))topic="food";
    else if(contains(text,{u8"учёб",u8"учеб",u8"работ",u8"экзамен",u8"урок",u8"школ",u8"универ",u8"дедлайн",u8"домашк"}))topic="work";
    else if(contains(text,{u8"девуш",u8"парень",u8"отношен",u8"любов",u8"друз",u8"друг",u8"люблю",u8"свидан"}))topic="people";
    else if(contains(text,{u8"игр",u8"катк",u8"стреля",u8"прицел",u8"прыж",u8"стрейф",u8"кс",u8" cs",u8"cs 1.6",u8"играю",u8"катаю",u8"тащу"}))topic="game";
    else if(!contains(text,{u8"ещё",u8"еще",u8"давай",u8"продолж",u8"согласен",u8"да",u8"нет"}))topic.clear();
    std::string answer;
    if(topic=="music")answer=choose({u8"Музыка — это серьёзно. Ты больше по тяжёлому басу, спокойному вайбу или чтобы соседи подпевали через стену?",u8"Есть треки «для фона», а есть «сейчас обязательно затащу». У тебя какой на репите?",u8"Что у тебя на репите? Только не говори «слушаю всё» — так обычно отвечают люди с плейлистом от радио в маршрутке."});
    else if(topic=="movies")answer=choose({u8"Кино обсуждаем. Ты за сюжет с поворотами или чтобы мозг отдыхал, а всё красиво взрывалось?",u8"Главный квест с сериалом — не досмотреть сезон до утра. Ты обычно проходишь его или проваливаешь?",u8"Чё любишь смотреть: комедию, триллер или чтобы два часа всё взрывалось, а ты просто ел?"});
    else if(topic=="fashion")answer=choose({u8"Шмот — это хорошо, пока чек не выглядит как покупка целого сервера. Что тебе важнее: силуэт, удобство или редкая вещь?",u8"Оверсайз — когда одежда свободная, а бюджет уже нет. Какую вещь сейчас хочешь?",u8"Мне нравится идея собрать образ вокруг одной заметной вещи, а остальное оставить спокойным. Ты за такой вариант или за полный хаос?"});
    else if(topic=="food")answer=choose({u8"Про еду лучше осторожно, я тут без рук и кухни. Ты сейчас хочешь быстро перекусить или нормально приготовить?",u8"Кофе и чай — две команды без нормального матчмейкинга. За кого играешь?",u8"Пицца после катки — сильный ход. Но клавиатуру соусом бафать не надо. Что обычно берёшь?"});
    else if(topic=="work")answer=choose({u8"С делами помогает маленькая цель: одна задача на 15 минут, потом пауза. Что сейчас больше всего откладываешь?",u8"Работа и учёба умеют давить. Давай разложим: что нужно сделать первым, без попытки спасти сразу всю неделю?",u8"Главное — не превращать «пять минут отдохну» в шестичасовую карьеру на сервере. Что у тебя за задача?"});
    else if(topic=="people")answer=choose({u8"С людьми сложнее, чем с настройками HUD: кнопки «сбросить к стандартным» нет. Что у тебя случилось?",u8"Я бы начал с прямого разговора, без угадывания мыслей. Ты уже говорил, что тебя беспокоит?",u8"Брат, иногда человеку нужно внимание, а не идеальный совет. Расскажи подробнее, только без чужих личных данных."});
    else if(topic=="game")answer=choose({u8"В игре лучший апгрейд иногда — короткая пауза после пары плохих раундов. Ты сейчас тренишь движение или просто отдыхаешь на сервере?",u8"Один красивый момент не требует десяти часов тильта. Что хочешь подтянуть: движение, стрельбу или спокойствие?",u8"Прицел можно настроить, дисциплину покупать придётся самому. Чем сегодня занимаешься в CS?"});
    else if(text==u8"да"||text==u8"ага"||text==u8"угу"||text==u8"ну да")answer=choose({u8"Принял. А теперь расширенная версия, не экономь буквы — они бесплатные. Что дальше?",u8"Ну вот, уже договорились. А тебе самому какой вариант больше нравится?",u8"Ага, говорит он, оставив мне работу телепатом. Давай чуть подробнее, брат."});
    else if(text==u8"нет"||text==u8"неа"||text==u8"не")answer=choose({u8"Значит, мимо. Как бы ты сам сделал?",u8"Окей, вычёркиваем. Что тогда подходит?",u8"Понял, этот вариант улетел в мусорку. Какой твой?"});
    else if(contains(text,{u8"норм",u8"хз",u8"понятно",u8"ясно"}))answer=choose({u8"Норм — это уже неплохо. А что могло бы сделать день прям хорошим?",u8"Коротко и загадочно, почти как ответ админа. Что у тебя сейчас вообще происходит?",u8"Ладно, без допроса. Хочешь обсудить что-нибудь или просто поболтаем?"});
    else if(contains(text,{u8"ахах",u8"хаха",u8"лол",u8"ору",u8"смешно"}))answer=choose({u8"Вот, уже не зря вкладку открыл. Держу марку. Ещё подкол или меняем тему?",u8"Смеёмся, пока жизнь не выставила счёт. Чё у тебя ещё интересного?",u8"Нормально, контакт установлен. Продолжаем этот цирк?"});
    else if(contains(text,{u8"сколько стоит",u8"кто президент",u8"какой курс",u8"сколько население",u8"сегодня погода",u8"курс валют"}))answer=u8"Свежую цифру не назову — её надо проверить. А ты для чего интересуешься?";
    else answer=choose({u8"Так, брат, это уже интереснее. А тебя в этом что больше цепляет?",u8"Погоди, не проскакивай самое интересное. И что было дальше?",u8"А сам ты к этому как относишься — нравится или бесит?",u8"Звучит как начало истории. Давай подробности, я весь внимание.",u8"Ладно, расклад такой: рассказывай, чего ты хочешь от этой ситуации. Тогда и обсудим по делу.",u8"О, тема подъехала. Ты уже решил, что делать, или пока прикидываешь варианты?",u8"Это ты сейчас серьёзно или мы уже на стадии «а давай сделаем дичь»?",u8"А что тебе самому кажется самым нормальным вариантом?",u8"Хорошо, а где тут главный прикол? Я чувствую, что ты недоговариваешь.",u8"Брат, с этого места подробнее. Что за движ вообще?",u8"У тебя сегодня день без скуки, я смотрю. Это давно так или только сейчас началось?",u8"Понял тебя. Что в этой теме хочется обсудить первым?"});
    if(swearing&&serial%5==0)answer=std::string(u8"Бля, брат. ")+answer;return answer;
}
static void save(){} // Conversation is deliberately session-only.
static void load(){
    if(loaded)return;loaded=true;
    history.push_back({false,u8"Здарова, брат. Чё у тебя?"});
    swearing=GetPrivateProfileIntA("interface","bratuha_swearing",1,iniPath)!=0;scroll=true;
}
static bool send(std::string text){
    if(!pending.empty()||text.empty()||text.size()>3000)return false;
    if(text.find_first_not_of(" \r\n\t")==std::string::npos)return false;
    history.push_back({true,std::move(text)});pending=reply(history.back().text);answerAt=GetTickCount64()+450;
    while(history.size()>119)history.erase(history.begin());scroll=true;save();return true;
}
static void tick(){if(!pending.empty()&&GetTickCount64()>=answerAt){history.push_back({false,std::move(pending)});pending.clear();scroll=true;save();}}
static void clear(){history.clear();pending.clear();topic.clear();scroll=true;save();}
}
